// Build daily report summary
const today = new Date().toLocaleDateString('en-CA'); // YYYY-MM-DD
const rows = $input.all().map(i => i.json);

let active = 0, expired = 0, expiringSoon = 0, pending = 0;
let expiringNames = [];
let expiredNames = [];
let pendingNames = [];
let totalFeeThisMonth = 0;

const thisMonth = today.slice(0, 7); // YYYY-MM

for (const r of rows) {
  if (!r.expiry_date) continue;

  const daysLeft = Math.round((new Date(r.expiry_date + 'T00:00:00') - new Date(today + 'T00:00:00')) / 86400000);

  if (r.payment_status === 'Pending') {
    pending++;
    pendingNames.push(r.name + ' (' + r.phone.slice(-4) + ')');
  } else if (daysLeft < 0) {
    expired++;
    expiredNames.push(r.name + ' (' + r.phone.slice(-4) + ')');
  } else {
    active++;
    if (daysLeft <= 5) {
      expiringSoon++;
      expiringNames.push(r.name + ' - ' + r.expiry_date + ' (' + daysLeft + 'd)');
    }
  }

  if ((r.last_payment_date || '').startsWith(thisMonth)) {
    totalFeeThisMonth += parseFloat(r.fee || 0);
  }
}

const report = [
  '*Body Line Fitness Center - Daily Report*',
  'Date: ' + today,
  '',
  'Total Members: ' + rows.length,
  'Active: ' + active,
  'Expired: ' + expired,
  'Pending Payment: ' + pending,
  'Expiring in 5 days: ' + expiringSoon,
  'Revenue This Month: Rs ' + totalFeeThisMonth,
  '',
  expiringSoon > 0 ? ('Expiring Soon:\n' + expiringNames.join('\n')) : '',
  expired > 0 ? ('Expired Members:\n' + expiredNames.slice(0,5).join('\n') + (expiredNames.length > 5 ? '... +' + (expiredNames.length-5) + ' more' : '')) : '',
  pending > 0 ? ('Pending Payment:\n' + pendingNames.slice(0,5).join('\n')) : ''
].filter(Boolean).join('\n');

return [{ json: { report, today, active, expired, pending, expiringSoon, totalFeeThisMonth } }];
